// Тақырыптық тест № 39, 6-сынып, «Жақшаларды ашу».
// Алынбағандар: PDF мәтіндік қабатында таңбалар мен бөлшектер бұзылған есептер (№1, 2, 4, 6, 7, 9, 14, 15, 19–37).
const testNo39 = imp('t39', 'НИШ', 'Тақырыптық тест № 39, 6-сынып (жақшаларды ашу)')([
  [3, 'eq', 1, 'Өрнекті ықшамдаңыз: –a – (a + 2b – (–b))', ['3b', '–a + 2b', '–2a – 3b', '–2a + 3b', '–3b'], 2,
    'a + 2b – (–b) = a + 3b. Сонда –a – (a + 3b) = –a – a – 3b = –2a – 3b.'],
  [5, 'eq', 1, 'Жақшаны ашып, өрнекті ықшамдаңыз: –a – (3a) + (–b) – b', ['–4a – 2b', '4a + 2b', '–2b + 4a', '3a – 2b', 'a + b'], 0,
    '–a – 3a = –4a, ал –b – b = –2b. Жауабы: –4a – 2b.'],
  [8, 'eq', 2, 'Өрнекті ықшамдаңыз: b – (b – a + (a – b) – (–a – b) + 2b) + 2a', ['1', '3a + 2b', '4b + 3a', 'a – 2b', '2'], 3,
    'Жақша іші: b – a + a – b + a + b + 2b = a + 3b. Сонда b – a – 3b + 2a = a – 2b.'],
  [10, 'eq', 2, 'Өрнекті ықшамдаңыз: m + [n – (m – n) – (n + m) + (m – n) + n] – m', ['m – n', 'n – m', '0', 'm – 1', '1'], 1,
    'Төртбұрышты жақша іші: n – m + n – n – m + m – n + n = n – m. Сонда m + (n – m) – m = n – m.'],
  [11, 'eq', 1, 'Өрнекті ықшамдаңыз: 1,4a – (2,5 – a) + (1,3 – 2,3a)', ['0', '1,9a – 1,2', '0,4a – 0,1', '0,2a + 2', '0,1a – 1,2'], 4,
    '1,4a – 2,5 + a + 1,3 – 2,3a = (1,4 + 1 – 2,3)a + (–2,5 + 1,3) = 0,1a – 1,2.'],
  [12, 'eq', 1, 'Өрнекті ықшамдаңыз: 2,8 – (4,2a + 3,4)', ['–0,6 – 4,2a', '6,2 + 4,2a', '1,2a – 4,2', '1,8a + 4,2', '0'], 0,
    '2,8 – 4,2a – 3,4 = –0,6 – 4,2a.'],
  [13, 'eq', 1, 'Өрнекті ықшамдаңыз: 5,36d + (–9,13d) + (–5,46d)', ['5,36d', '–9,23d', '–9,03d', '–5,46d', '8,30d'], 1,
    '5,36 – 9,13 – 5,46 = –9,23, яғни –9,23d.'],
  [16, 'eq', 2, 'Өрнекті ықшамдаңыз: 7b – 3a – (b – 3a – (3b – 2a)) + 3a', ['3b – a', '4b + 3a', '5a + 2b', '6a + 3b', '9b + a'], 4,
    'Ішкі жақша: b – 3a – 3b + 2a = –2b – a. Сонда 7b – 3a + 2b + a + 3a = 9b + a.'],
  [17, 'eq', 2, 'Өрнекті ықшамдаңыз: a – (a – b – (a + b) – (–b + a) + b)', ['4a', '3a', '2a + b', '3a – b', '2a'], 4,
    'Жақша іші: a – b – a – b + b – a + b = –a. Сонда a – (–a) = 2a.'],
  [18, 'eq', 2, 'Өрнекті ықшамдаңыз: a + b – (a – (–b + a) + (a – b) – b) – a', ['2b – a', '0', 'a', '3b + a', '7'], 0,
    'Жақша іші: a + b – a + a – b – b = a – b. Сонда a + b – a + b – a = 2b – a.'],
]);

